     "num": 1,
     "q": "【汉译英】假如这位老师耐心帮助每一名学生，他就会减少课堂阻力，并注意到成绩一致的稳步提升。",
     "part": 0,
     "a": "译文：If this teacher assisted every student patiently, he would reduce resistance in class and notice a noticeable, consistent improvement.　|　解析：串词：assist（as-=去+sist=站→站过去帮忙=帮助）｜reduce（re-=回+duce=引→引回=减少）｜notice（not=知道/标记+-ice→注意）；语法：虚拟语气·if与现在事实相反（if+一般过去时，主句would+动词原形）；S+V+O；词根：sist=站、duce=引、not=知道。"
